using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_AllTargets", menuName = "Data/Battle/Logics/Enemy Action/All Targets")]
public class EnemyActionLogic_AllTargets : EnemyActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentActiveUnits currentActiveUnits;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		List<GameObject> targets = currentActiveUnits.GetCurrentActiveUnits();
		if (actionAmount == EffectsValues.NO_VALUE)
		{
			battleAction.AreaCastTarget(targets, source);
		}
		else
		{
			battleAction.AreaCastTargetAmount(targets, actionAmount, source);
		}
	}

	public override List<GameObject> GetActionTargets()
	{
		return currentActiveUnits.GetCurrentActiveUnits();
	}
}
